      border: 1px solid rgba(255, 255, 255, 0.55);
      border-radius: 18px;
      color: #263b32;
      background: rgba(248, 244, 231, 0.78);
      box-shadow: 0 12px 40px rgba(30, 55, 45, 0.14);
      backdrop-filter: blur(12px);
